6	/** IP-Adresse aus der Anfrage (hinter Proxy/Load-Balancer aus X-Forwarded-For bzw. X-Real-IP). */
7	export function ipAdresse(request) {
8	  const ip = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() || request.headers.get("x-real-ip")?.trim() || "";
9	  return /^[0-9a-f.:]{3,45}$/i.test(ip) ? ip : "";
10	}
